insert into public.ppg_lesson_steps
  (lesson_key, order_index, kind, body_th, body_en, check_prompt_th, check_prompt_en, check_answer_key, check_explanation_th, check_explanation_en)
values
  ('chapter-01-lesson-02', 1, 'objective', 'เมื่อจบบทเรียนนี้ คุณจะเลือกข้อมูลและโปรแกรมนำเสนอให้เหมาะกับงานได้', 'By the end you can choose information and a presentation program that fit the job.', null, null, null, null, null),
  ('chapter-01-lesson-02', 2, 'explanation', '## ประเภทของการนำเสนอข้อมูล

การนำเสนองานมีความจำเป็นและเป็นที่ยอมรับกันในระบบการทำงาน เพราะช่วยให้การปฏิบัติงานบรรลุจุดมุ่งหมายและพัฒนางานได้รวดเร็วยิ่งขึ้น การนำไปใช้นั้นขึ้นอยู่กับลักษณะของงาน ประเภทของการนำเสนอแบ่งออกเป็นส่วนใหญ่ ๆ 2 รูปแบบ ดังนี้

4.1 การนำเสนอแบบเฉพาะกลุ่ม เป็นการนำเสนอข้อมูลต่าง ๆ ต่อผู้ที่มีหน้าที่เกี่ยวข้องหรือผู้ที่ได้รับเชิญให้เข้าร่วมฟังข้อมูลในการนำเสนอ

4.2 การนำเสนอแบบสาธารณะ เป็นการนำเสนอข้อมูลต่าง ๆ ที่เปิดโอกาสให้บุคคลทั่วไปเข้าร่วมฟังการนำเสนอได้ มีการเปิดโอกาสให้ผู้ฟังได้ซักถามหรือแสดงความคิดเห็น', '', null, null, null, null, null),
  ('chapter-01-lesson-02', 3, 'explanation', '## 5. ลักษณะของข้อมูลที่นำเสนอ

การนำเสนอสามารถนำข้อมูลที่มีลักษณะแตกต่างกันมาร่วมนำเสนอได้ ซึ่งขึ้นอยู่กับจุดประสงค์ของผู้นำเสนอ ข้อมูลที่จะนำเสนอแบ่งออกตามลักษณะของข้อมูลได้ 2 ลักษณะ ได้แก่

5.1 ข้อเท็จจริง คือ ข้อความที่เกี่ยวข้องกับเหตุการณ์ เรื่องราวความเป็นมาหรือความเป็นอยู่ตามความจริง อาจเป็นความรู้ที่ได้จากการทดสอบหรือทดลองทางวิทยาศาสตร์ สามารถนำมาใช้เป็นหลักฐานข้ออ้างอิงสำหรับอ้างอิงในการพิสูจน์สิ่งใดสิ่งหนึ่ง

5.2 ข้อคิดเห็น เป็นความเห็นซึ่งเกิดจากประเด็นหรือเรื่องราวที่ชวนให้คิด อาจเป็นความรู้สึก ความเชื่อถือ หรือแนวคิดที่ผู้นำเสนอมีต่อสิ่งหนึ่งสิ่งใด ความเห็นอาจแตกต่างกัน ขึ้นอยู่กับพื้นฐานและประสบการณ์ของแต่ละบุคคล', '', null, null, null, null, null),
  ('chapter-01-lesson-02', 4, 'explanation', '## 6. โปรแกรมที่ใช้ในการนำเสนอ

โปรแกรมที่ใช้ในการนำเสนองานมีให้เลือกใช้งานหลายโปรแกรม ส่วนช่องทางการนำเสนอผลงานมี 2 ช่องทาง คือ แบบออฟไลน์ (Offline) โดยรวมใช้โปรแกรม PowerPoint นำเสนองาน หรือโปรแกรมสร้างสื่อ (CAI ย่อมาจาก Computer Assisted Instruction หมายถึงคอมพิวเตอร์ช่วยสอน) และช่องทางแบบออนไลน์ (Online) คือเว็บไซต์ในการนำเสนองาน ตัวอย่างโปรแกรมการนำเสนอ มีดังนี้

### 6.1 โปรแกรม Microsoft PowerPoint

เป็นโปรแกรมการนำเสนอข้อมูลที่มีผู้ใช้มาก เพราะใช้งานง่ายที่สุด มีคุณภาพ สามารถเชื่อมต่อเข้ากับเครื่องโปรเจกเตอร์ เพื่อนำเสนอในห้องประชุมหรือต่อบุคคลจำนวนมากได้

### 6.2 โปรแกรม Adobe Animate

คือโปรแกรมสร้างแอนิเมชัน เป็นหนึ่งในชุดโปรแกรม Adobe Creative Cloud ถูกสร้างขึ้นเพื่อพัฒนาไฟล์ภาพเคลื่อนไหว หรือแอนิเมชันบนเว็บไซต์ ที่เรียกกันว่า Web Animation สามารถสร้าง Interactive หรือการโต้ตอบกับผู้เข้าเยี่ยมชมเว็บไซต์บนเว็บไซต์ต่าง ๆ ได้ ซึ่งพัฒนามาจาก Adobe Flash Professional เป็น Adobe Animate ที่ออกมาให้ใช้งานกัน พร้อมฟังก์ชันที่ทำงานได้สะดวกสบายมากขึ้น

### 6.3 โปรแกรมนำเสนองานออนไลน์หลายโปรแกรม

เช่น โปรแกรมสร้างงานนำเสนอ Google Slides โปรแกรมสร้างสื่อการสอนออนไลน์ Canva และโปรแกรม Prezi ฯลฯ', '', null, null, null, null, null),
  ('chapter-01-lesson-02', 5, 'explanation', '## 7. หลักการของการนำเสนอ

การสร้างงานนำเสนอที่ดีและน่าสนใจ ตามหลักการของการนำเสนอตามสไตล์ Zen ซึ่งเป็นการออกแบบการนำเสนออย่างเรียบง่ายและตรงประเด็น ดังนี้

### 7.1 Big คือ ตัวอักษรใหญ่ อ่านได้ชัดเจน แม้จะอยู่ไกล

### 7.2 Clear คือ ข้อความกระชับ ชัดเจน ตรงประเด็น

### 7.3 Clean คือ เรียบร้อย ไม่รก สะอาดตา

7.4 Simple คือ เรียบง่าย ไม่ซับซ้อน เนื่องจากผู้อ่านจะได้เข้าใจได้ง่าย

7.5 Story คือ มีการเล่าเรื่องที่น่าสนใจ โดยมีทั้งเทคนิคการเล่าในหลายลักษณะ ต้องเข้าใจถึงเป้าหมายของการนำเสนอ (Objective) กลุ่มผู้ฟัง (Audience)

7.6 Good Presentation Technique คือ มีเทคนิคการนำเสนอที่ดี มีแอนิเมชันประกอบเพื่อช่วยสื่อสารกับผู้ฟัง หลายส่วนเป็น Soft Skills หรือทักษะนุ่ม คือ ทักษะส่วนบุคคลที่เกี่ยวข้องกับอุปนิสัย บุคลิกภาพ ทัศนคติ และความสามารถในการปฏิสัมพันธ์กับผู้อื่นที่ต้องอาศัยศิลปะในการนำเสนอ หลายส่วนเป็นเทคนิคที่ต้องอาศัยการเรียนรู้และประสบการณ์ที่จะทำให้การสร้างงานนำเสนอเป็นมืออาชีพมากยิ่งขึ้น', '', null, null, null, null, null),
  ('chapter-01-lesson-02', 6, 'check', '', '', 'เมื่อต้องเปรียบเทียบยอดขายสามสาขา ควรใช้ข้อมูลประเภทใด', 'To compare sales across three branches, which information type works best?', 'b', 'แผนภูมิแท่งเปรียบเทียบค่าหลายกลุ่มได้ชัดเจนกว่าข้อความยาว', 'A bar chart compares values across groups more clearly than a long paragraph.'),
  ('chapter-01-lesson-02', 7, 'summary', 'เลือกข้อมูลให้ตรงกับคำถาม และเลือกโปรแกรมให้ตรงกับทีมและอุปกรณ์', 'Match the information to the question and the program to your team and devices.', null, null, null, null, null);
