คลิกปุ่ม X (Close) เพื่อปิดออกจากหน้าต่างโปรแกรม Microsoft PowerPoint', '', null, null, null, null, null),
  ('chapter-03-lesson-02', 7, 'check', '', '', 'เพลซโฮลเดอร์คืออะไร', 'What is a placeholder?', 'b', 'เพลซโฮลเดอร์คือกล่องที่เค้าโครงสไลด์เตรียมตำแหน่งและรูปแบบไว้แล้ว คุณเพียงคลิกและพิมพ์', 'A placeholder is a box whose position and formatting come from the layout; you only click and type.'),
  ('chapter-03-lesson-02', 8, 'summary', 'เลือกเลย์เอาต์ให้พอดีกับเนื้อหา จากนั้นใช้เพลซโฮลเดอร์ช่วยจัดวางเร็วขึ้น', 'Match the layout to the content, and let placeholders make placement faster.', null, null, null, null, null);
